-- Oracle load script for the DA3 dataset (same data as the CSVs). Run as user ACADEMIC AFTER 01_schema.sql.
-- IMPORTANT: the data contains the ampersand character (Security and Privacy track); without the next line SQL*Plus asks for substitution values
SET DEFINE OFF
SET SQLBLANKLINES ON
SET FEEDBACK OFF
-- The block below clears any earlier sample rows.
DELETE FROM PRESENTATION;
DELETE FROM PAPER_KEYWORD;
DELETE FROM KEYWORD;
DELETE FROM SUBMISSION;
DELETE FROM REVIEW;
DELETE FROM PAPER_REVIEWER;
DELETE FROM PAPER_AUTHOR;
DELETE FROM PAPER;
DELETE FROM REVIEWER;
DELETE FROM AUTHOR;
DELETE FROM SESSION_TBL;
DELETE FROM TRACK;
DELETE FROM CONFERENCE;

-- trg_no_self_review will fire on these inserts; none of them is a conflict
-- NOTE: trg_flag_paper fires on score>=9 and may set Status='Accepted'; statuses were generated to agree with that rule
COMMIT;
SET FEEDBACK ON
-- Sequences are created in 01_schema.sql with start values AFTER the ids used here, so sp_add_paper will not collide.
